    fn find_free_space(&self, row: usize) -> (a: Attempt)
        requires self.wf(), 0 <= row < HEIGHT,
        ensures (match a {
            Attempt::Free(c) => 0 <= c < WIDTH,
            Attempt::Unfree(c, key) => 0 <= c < WIDTH
