            0 <= old_row < HEIGHT,
            0 <= new_row < HEIGHT,
            0 <= old_col < WIDTH,
            0 <= new_col < WIDTH,
            old_row != new_row,
            old_row == hash1(key) || old_row == hash2(key),
            new_row == hash1(key) || new_row == hash2(key),
    {
